export function getEngineSpec(id: string): EngineSpec | undefined {
  return ENGINE_SPECS.find((s) => s.id === id)
}

/** 引擎的全部输入行（主输入 + 可选第二输入）。 */
export function engineInputs(spec: EngineSpec): EngineInputSpec[] {
  return spec.secondInput !== undefined ? [spec.input, spec.secondInput] : [spec.input]
}
